class SystemController:
    def __init__(self):
        self.session_timeout = 900  # 15 minutes in seconds
        self.sessions = {}

    def login(self, user_id):
        session_id = self._generate_session_id()
        self.sessions[session_id] = {'user_id': user_id, 'last_activity': time.time()}
        return session_id

    def logout(self, session_id):
        if session_id in self.sessions:
            del self.sessions[session_id]

    def _generate_session_id(self):
        import uuid
        return str(uuid.uuid4())

    def keep_alive(self, session_id):
        if session_id in self.sessions:
            self.sessions[session_id]['last_activity'] = time.time()

    def check_session(self, session_id):
        if session_id in self.sessions:
            last_activity = self.sessions[session_id]['last_activity']
            if time.time() - last_activity > self.session_timeout:
                self.logout(session_id)
                return False
            return True
        return False

